import 'package:flutter/material.dart';

class SModal extends StatelessWidget { const SModal({super.key, required this.title, required this.child, this.actions}); final String title; final Widget child; final List<Widget>? actions; @override Widget build(BuildContext context) => AlertDialog(shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)), title: Text(title), content: child, actions: actions); }
class SConfirmDialog extends StatelessWidget { const SConfirmDialog({super.key, required this.title, required this.message, required this.onConfirm}); final String title, message; final VoidCallback onConfirm; @override Widget build(BuildContext context) => SModal(title: title, child: Text(message), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Annuler')), FilledButton(onPressed: () { Navigator.pop(context); onConfirm(); }, child: const Text('Confirmer'))]); }
class SBottomSheet extends StatelessWidget { const SBottomSheet({super.key, required this.child, this.title}); final Widget child; final String? title; @override Widget build(BuildContext context) => SafeArea(child: Padding(padding: const EdgeInsets.fromLTRB(20, 12, 20, 24), child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [Center(child: Container(width: 40, height: 4, decoration: BoxDecoration(color: const Color(0xFF4A2630), borderRadius: BorderRadius.circular(99)))), if (title != null) Padding(padding: const EdgeInsets.only(top: 20, bottom: 12), child: Text(title!, style: Theme.of(context).textTheme.titleLarge)), child]))); }
